class OilCompany {}
class GasStation {}
class Pump {}
class Reservoir {}
class GasolineType {}
class Customer {}
class RefuelTurn {}
class RefuelCard {}
class MonthlyInvoice {}
class Payment {}
class DailyReport {}

GasStation "1" -- "*" Pump : possesses
Pump "1" -- "1" Reservoir : has
Pump "1" -- "1" GasolineType : contains
Pump "0..1" -- "0..1" Customer : refuels
Pump "1" -- "1" Pump : blocks

Reservoir "1" -- "1" Pump : belongs to

Customer "1" -- "*" RefuelTurn : performs
Customer "1" -- "0..1" RefuelCard : holds
Customer "1" -- "*" MonthlyInvoice : receives
Customer "1" -- "*" Payment : makes

MonthlyInvoice "1" -- "*" RefuelTurn : includes
MonthlyInvoice "1" -- "*" Payment : is paid by

DailyReport ..> Pump : indicates

@enduml

